def _text(u,v,txt,x,y,k=.075):
 a=int((u-x)/k);b=int((v-y)/k)
 if u<x or v<y or b>=5 or a>=len(txt)*4:return False
 return a%4<3 and _GLYPHS.get(txt[a//4],['000']*5)[b][a%4]=='1'
def _point(e,fn,s,t):
 f=e['from'];a=e['to'];axes={'north':(2,0,0,False,1,False),'south':(2,1,0,True,1,False),'east':(0,1,2,False,1,False),'west':(0,0,2,True,1,False),'up':(1,1,0,True,2,True),'down':(1,0,0,True,2,False)}
